{
 "schema_version": "1.1",
 "reviewer": "design_intent",
 "findings": [
  {
   "id": "F-5c95f2712e",
   "rule_id": "MF-005",
   "category": "design_intent",
   "requirement": "Heat treatment and hardness are specified where required, with the stage they apply at",
   "result": "warning",
   "severity": "major",
   "evidence": [
    {
     "kind": "note",
     "ref": "N3",
     "page": 1,
     "bbox": null,
     "quote": "HEAT TREATMENT NOTE :- 1) TO BE CASE HARDENED UPTO 56~60 HRC. 2) CASE DEPTH 0.8~1.2mm. 3) THREADS TO BE KEEP SOFT. 4) RETAPPING TO BE DONE AFTER SURFACE TREATMENT AT SUPPLIER END.( IF APPLICABLE )",
     "provenance": "pdf_text"
    }
   ],
   "comment": "The heat treatment note specifies case hardening and hardness limits but fails to explicitly state the stage at which the heat treatment must be performed (e.g., 'before final grinding' or 'after rough machining'). This omission matters because case hardening causes distortion; without a defined stage, the manufacturer may machine to final dimensions before hardening, leading to out-of-tolerance parts after treatment. The designer should add the processing stage to the heat treatment note.",
   "recommended_correction": "Add the manufacturing stage for heat treatment (e.g., 'Perform case hardening after rough machining and before final grinding') to Note N3.",
   "reviewer": "design_intent",
   "source": "llm"
  }
